mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END
FROM orders
WHERE idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE positions
SET
qty = #{quantity},
avg_cost = #{averageCost}
WHERE account_id = #{accountId}
AND symbol = #{symbol}

UPDATE positions
SET
qty = #{quantity},
avg_cost = #{averageCost},
version = version + 1
WHERE account_id = #{accountId}
AND symbol = #{symbol}
AND version = #{expectedVersion}

UPDATE orders
SET status = #{newStatus}
WHERE id = #{orderId}
AND status = #{expectedStatus}

UPDATE orders
SET status = #{newStatus}
WHERE id = #{orderId}
AND status = #{expectedStatus}

mapper.select:
SELECT CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END
FROM executions
WHERE event_id = #{eventId}

SELECT CAST(o.id AS VARCHAR) AS id, o.account_id, o.symbol, o.side, o.qty, o.price, e.price AS executed_price, o.status, o.idempotency_key, i.currency, o.created_on FROM orders o LEFT JOIN executions e ON o.id = e.order_id AND e.id = (SELECT id FROM executions WHERE order_id = o.id ORDER BY created_at DESC LIMIT 1) LEFT JOIN instruments i ON o.symbol = i.symbol WHERE o.account_id = #{accountId}
AND o.status = #{status}
AND o.created_on >= #{from}
AND o.created_on <= #{to}
ORDER BY o.created_on DESC
